  { g: 'Random & math', n: ['dist'], s: 'dist(x1, y1, x2, y2)', d: 'Distance between two points.' },
  { g: 'Random & math', n: ['sign'], s: 'sign(v)', d: '-1, 0 or 1.' },
  { g: 'Random & math', n: ['wrap'], s: 'wrap(v, n)', d: 'Modulo that also works for negative numbers: `wrap(-1, 5)` is 4.' },

  { g: 'Time', n: ['every'], s: 'every(n)', d: 'True once every `n` frames (the game runs at 60 frames per second).', e: 'if (every(60)) seconds++' },
  { g: 'Time', n: ['now'], s: 'now()', d: 'Wall-clock time in seconds (use it with `save`/`load` for things that continue while the game is closed).' },

  { g: 'Actors', n: ['kind'], s: 'kind(sprite, k = WHITE, z = 1)', d: 'Defines a type of moving object: its sprite, color and scale.', e: "const coin = kind('coin', YELLOW, 2)" },
  { g: 'Actors', n: ['add'], s: 'add(kind, x, y, props)', d: 'Creates an object (an "actor") with fields `x y vx vy w h c on k`. `props` overrides fields. Returns the actor.', e: 'add(coin, R(W), 0, { vy: 2 })' },
  { g: 'Actors', n: ['all'], s: 'all(kind)', d: 'Array of living actors of a kind (all kinds when omitted).' },
  { g: 'Actors', n: ['each'], s: 'each(kind, fn)', d: 'Calls `fn(actor)` for every living actor of a kind.', e: 'each(coin, a => a.vy += .1)' },
  { g: 'Actors', n: ['kill'], s: 'kill(actor)', d: 'Removes an actor (at the next `step`).' },
  { g: 'Actors', n: ['touch'], s: 'touch(kindA, kindB, fn)', d: 'Calls `fn(a, b)` for every pair that overlaps.', e: 'touch(player, coin, (p, c) => { kill(c); score++ })' },
  { g: 'Actors', n: ['hit'], s: 'hit(a, b)', d: 'True when two objects with `x y w h` overlap.' },
  { g: 'Actors', n: ['step'], s: 'step()', d: 'Moves every actor by its speed (`vx`, `vy`) and removes the dead ones. Call once per frame.' },
  { g: 'Actors', n: ['draw'], s: 'draw()', d: 'Draws every actor with its sprite. Call once per frame.' },
  { g: 'Actors', n: ['clear'], s: 'clear()', d: 'Removes all actors.' },

  { g: 'Grids & paths', n: ['grid'], s: 'grid(cols, rows, fill = 0)', d: 'A flat array of `cols * rows` cells with the extra fields `.c` and `.r`.', e: 'const map = grid(16, 11, 0)' },
  { g: 'Grids & paths', n: ['gget'], s: 'gget(grid, x, y)', d: 'Value of a cell, or -1 outside the grid.' },
  { g: 'Grids & paths', n: ['gset'], s: 'gset(grid, x, y, value)', d: 'Sets a cell (ignored outside the grid).' },
  { g: 'Grids & paths', n: ['flood'], s: 'flood(cols, rows, sx, sy, max, cost)', d: 'Cheapest walking cost from (sx, sy) to every cell, as an array of `cols * rows` numbers (-1 = not reachable within `max`). `cost(x, y)` returns the price of entering a cell, or anything that is not a number to block it. 4-way movement.', e: 'const D = flood(16, 11, ux, uy, 3, (x, y) => map[y*16+x] == 1 ? 2 : map[y*16+x] > 1 ? null : 1)' },

  { g: 'Sound', n: ['s'], s: 's(hz, ms = 70, type = "square")', d: 'Plays a beep.', e: 's(880)' },
  { g: 'Sound', n: ['mel'], s: 'mel(notes, ms = 100, type)', d: 'Plays a melody: an array of frequencies, 0 = rest.', e: 'mel([523, 659, 784, 1047], 120)' },
  { g: 'Sound', n: ['resume'], s: 'resume()', d: 'Engine internal.', hide: true },

  { g: 'Storage', n: ['save'], s: 'save(key, value)', d: 'Writes a value (anything JSON can hold: numbers, text, lists, objects) to this game\'s private memory on this device. The memory belongs to the game alone: it is keyed by a fingerprint of the game\'s code (comments and spacing do not count), so no other game can read or change it, and a game whose code changed starts with an empty memory. About 1.5 KB per value, 32 keys. It lets a game go on while it is closed: save the time with `now()` and replay it on the next start (see the Tiny Pet demo).', e: "save('best', score)" },
  { g: 'Storage', n: ['load'], s: 'load(key, default)', d: 'Reads a stored value (or `default` when nothing was saved).', e: "best = load('best', 0)" }
